/* 宝可梦大赛报名处 — single-scene, client-only Phaser 3 game.
 * Map: assets/arena.json (generated by build_map.py). Tiles + player sprite from
 * ariroffe/personal-website (MIT code; art credits in README).
 * Movement is tile-by-tile like the GBA games; no server state. */
(function () {
  'use strict';

  const TILE = 32;
  const STEP_MS = 180;          // time to walk one tile
  const DIRS = {
    left:  { dx: -1, dy: 0, anim: 'left' },
    right: { dx: 1,  dy: 0, anim: 'right' },
    up:    { dx: 0,  dy: -1, anim: 'back' },
    down:  { dx: 0,  dy: 1,  anim: 'front' },
  };

  const TEXT = {
    zh: {
      npc: [
        '欢迎来到宝可梦大赛报名处！',
        '这里是本届宝可梦大赛的报名柜台。',
        '报名系统还在准备中，开放后再来找我吧！',
      ],
      hint: '方向键 / WASD 移动，空格 / 回车 对话',
      hintTouch: '方向键移动，走到柜台前按 A 对话',
      next: '▼',
    },
    en: {
      npc: [
        'Welcome to the Pokémon Contest reception!',
        'This is the entry desk for this season\'s contest.',
        'Registration isn\'t open yet. Come back and see me later!',
      ],
      hint: 'Arrows / WASD to move, Space / Enter to talk',
      hintTouch: 'D-pad to move, press A at the counter to talk',
      next: '▼',
    },
  };
  const lang = () => (window.I18n && window.I18n.lang === 'en' ? 'en' : 'zh');

  // ---------- dialog box (DOM, so CJK text renders crisply and is screen-reader friendly) ----------
  const dialog = {
    el: null, textEl: null, lines: [], idx: 0, typing: null, open: false,
    init() {
      this.el = document.getElementById('dialog');
      this.textEl = document.getElementById('dialog-text');
      this.el.addEventListener('click', () => this.advance());
    },
    start(lines) {
      this.lines = lines; this.idx = 0; this.open = true;
      this.el.hidden = false;
      this.show();
    },
    show() {
      const full = this.lines[this.idx];
      let n = 0;
      clearInterval(this.typing);
      this.textEl.textContent = '';
      this.el.setAttribute('aria-label', full);
      this.typing = setInterval(() => {
        n++;
        this.textEl.textContent = full.slice(0, n);
        if (n >= full.length) { clearInterval(this.typing); this.typing = null; }
      }, 35);
    },
    advance() {
      if (!this.open) return;
      if (this.typing) {            // first press finishes the line
        clearInterval(this.typing); this.typing = null;
        this.textEl.textContent = this.lines[this.idx];
        return;
      }
      this.idx++;
      if (this.idx >= this.lines.length) this.close();
      else this.show();
    },
    close() {
      this.open = false; this.el.hidden = true;
      clearInterval(this.typing); this.typing = null;
    },
  };

  // ---------- virtual pad (touch) ----------
  const pad = { held: null, action: false };
  function bindPad() {
    document.querySelectorAll('#pad [data-dir]').forEach(btn => {
      const dir = btn.dataset.dir;
      const down = e => { e.preventDefault(); pad.held = dir; };
      const up = e => { e.preventDefault(); if (pad.held === dir) pad.held = null; };
      btn.addEventListener('pointerdown', down);
      btn.addEventListener('pointerup', up);
      btn.addEventListener('pointerleave', up);
      btn.addEventListener('pointercancel', up);
    });
    const a = document.getElementById('pad-a');
    a.addEventListener('pointerdown', e => { e.preventDefault(); pad.action = true; });
  }

  class Arena extends Phaser.Scene {
    constructor() { super('arena'); }

    preload() {
      this.load.image('tiles', 'assets/tileset.png');
      this.load.tilemapTiledJSON('map', 'assets/arena.json');
      this.load.atlas('player', 'assets/player.png', 'assets/player.json');
    }

    create() {
      const map = this.make.tilemap({ key: 'map' });
      const ts = map.addTilesetImage('tileset', 'tiles', 32, 32, 1, 2);
      ['Ground1', 'Ground2', 'Collision1', 'Collision2'].forEach(n => map.createLayer(n, ts, 0, 0));
      map.createLayer('Above', ts, 0, 0).setDepth(10);

      const prop = k => (map.properties.find(p => p.name === k) || {}).value;
      this.solid = JSON.parse(prop('solid'));
      const [sx, sy] = prop('spawn').split(',').map(Number);
      const [nx, ny] = prop('npc').split(',').map(Number);
      this.npc = { x: nx, y: ny };
      this.mapW = map.width; this.mapH = map.height;

      // Player: 32x41 sprite, feet on the bottom of its tile
      this.tx = sx; this.ty = sy; this.facing = 'up'; this.moving = false;
      this.player = this.add.sprite(0, 0, 'player', 'ariel-back').setOrigin(0.5, 1).setDepth(5);
      this.placePlayer();
      for (const k of ['left', 'right', 'front', 'back']) {
        this.anims.create({
          key: k,
          frames: this.anims.generateFrameNames('player', { prefix: `ariel-${k}-walk.`, start: 0, end: 3, zeroPad: 3 }),
          frameRate: 10, repeat: -1,
        });
      }

      const cam = this.cameras.main;
      cam.startFollow(this.player, true);
      cam.setRoundPixels(true);
      this.fitCamera();
      this.scale.on('resize', () => this.fitCamera());

      this.keys = this.input.keyboard.addKeys('UP,DOWN,LEFT,RIGHT,W,A,S,D,SPACE,ENTER,Z');
      const talk = () => this.interact();
      this.keys.SPACE.on('down', talk);
      this.keys.ENTER.on('down', talk);
      this.keys.Z.on('down', talk);
      this.input.on('pointerdown', () => { if (dialog.open) dialog.advance(); });

      const setHint = () => {
        const t = TEXT[lang()];
        document.getElementById('hint').textContent = matchMedia('(pointer: coarse)').matches ? t.hintTouch : t.hint;
      };
      setHint();
      window.onArenaLang = setHint;
    }

    fitCamera() {
      // Integer zoom so pixels stay square; show the whole room when there's room for it.
      const { width, height } = this.scale.gameSize;
      const mw = this.mapW * TILE, mh = this.mapH * TILE;
      const fit = Math.min(width / mw, height / mh);
      // Half-step zoom keeps pixels even on desktop; small screens shrink to fit the whole room.
      const zoom = fit >= 1 ? Math.floor(fit * 2) / 2 : Math.max(0.5, fit);
      const cam = this.cameras.main;
      cam.setZoom(zoom);
      // When the room is smaller than the view, widen the bounds symmetrically so it sits centered.
      const vw = width / zoom, vh = height / zoom;
      const bw = Math.max(mw, vw), bh = Math.max(mh, vh);
      cam.setBounds((mw - bw) / 2, (mh - bh) / 2, bw, bh);
    }

    placePlayer() {
      this.player.setPosition(this.tx * TILE + TILE / 2, (this.ty + 1) * TILE);
    }

    blocked(x, y) {
      return x < 0 || y < 0 || x >= this.mapW || y >= this.mapH || this.solid[y][x] === 1;
    }

    face(dir) {
      this.facing = dir;
      this.player.anims.stop();
      this.player.setFrame(`ariel-${DIRS[dir].anim}`);
    }

    interact() {
      if (dialog.open) { dialog.advance(); return; }
      if (this.moving) return;
      const d = DIRS[this.facing];
      const fx = this.tx + d.dx, fy = this.ty + d.dy;
      // NPC stands behind the counter: talk across it (facing up at the counter tile in front of her)
      const acrossCounter = this.facing === 'up' && fx === this.npc.x && fy === this.npc.y + 2;
      const adjacent = fx === this.npc.x && fy === this.npc.y;
      if (acrossCounter || adjacent) dialog.start(TEXT[lang()].npc);
    }

    heldDir() {
      const k = this.keys;
      if (k.LEFT.isDown || k.A.isDown) return 'left';
      if (k.RIGHT.isDown || k.D.isDown) return 'right';
      if (k.UP.isDown || k.W.isDown) return 'up';
      if (k.DOWN.isDown || k.S.isDown) return 'down';
      return pad.held;
    }

    update() {
      if (pad.action) { pad.action = false; this.interact(); }
      if (this.moving || dialog.open) return;
      const dir = this.heldDir();
      if (!dir) {
        if (this.player.anims.isPlaying) this.face(this.facing);
        return;
      }
      const d = DIRS[dir];
      this.facing = dir;
      const nx = this.tx + d.dx, ny = this.ty + d.dy;
      if (this.blocked(nx, ny)) { this.face(dir); return; }
      this.moving = true;
      this.player.anims.play(d.anim, true);
      this.tx = nx; this.ty = ny;
      this.tweens.add({
        targets: this.player,
        x: nx * TILE + TILE / 2,
        y: (ny + 1) * TILE,
        duration: STEP_MS,
        onComplete: () => { this.moving = false; },
      });
    }
  }

  function boot() {
    dialog.init();
    bindPad();
    const host = document.getElementById('game');
    new Phaser.Game({
      type: Phaser.AUTO,
      parent: host,
      pixelArt: true,
      backgroundColor: '#04241f',
      scale: { mode: Phaser.Scale.RESIZE, width: host.clientWidth, height: host.clientHeight },
      scene: Arena,
    });
  }
  window.addEventListener('DOMContentLoaded', boot);
})();
